window.AUTH=window.AUTH||{};window.AUTH["21-857"]={"d":"21-857","id":"2022/21-857","n":"Jones v. Hendrix","briefs":[{"k":"petitioner","label":"Brief of petitioner Marcus DeAngelo Jones","date":"2022-07-14","url":"https://www.supremecourt.gov/DocketPDF/21/21-857/230051/20220714094933784_21-857_Brief%20for%20Petitioner.pdf","side":"pet","n":80},{"k":"respondent","label":"Brief of respondent Dewayne Hendrix, Warden supporting affirmance","date":"2022-08-08","url":"https://www.supremecourt.gov/DocketPDF/21/21-857/233024/20220808182056765_21-857bsUnitedStates.pdf","side":"res","n":67},{"k":"reply","label":"Reply of petitioner Marcus DeAngelo Jones","date":"2022-10-12","url":"https://www.supremecourt.gov/DocketPDF/21/21-857/242898/20221012075828192_No.%2021-857_Reply%20Brief%20for%20Petitioner.pdf","side":"pet","n":38}],"opinion":"https://www.supremecourt.gov/opinions/22pdf/599us1r42_2b35.pdf","tr":true,"items":[{"t":"case","label":"Boumediene v. Bush","cite":"553 U.S. 723","y":2008,"id":"2007/06-1195","sc":1,"by":{"0":"14, 34, 46","1":"15, 18","2":"5, 12"},"q":[{"src":"brief","b":0,"text":"meaningful opportunity to demonstrate that he is being held pursuant to ‘the erroneous application or interpretation’ of relevant law.","cite":"553 U.S. 723, 779"},{"src":"brief","b":0,"text":"entitles the prisoner to a meaningful opportunity to demonstrate that he is being held pursuant to ‘the erroneous application or interpretation’ of relevant law.","cite":"553 U.S. 723, 779"},{"src":"brief","b":1,"text":"uphold[] the statute[] against constitutional challenges.","cite":"553 U.S. at 776"},{"src":"brief","b":2,"text":"uphold[ ] the statute[ ] against constitutional challenges.","cite":"553 U.S. 723, 776"},{"src":"argument","who":"Mr. Feigin","text":"But I think the bottom line, Your Honor, is the way we're interpreting it now is the way that the Court actually interpreted it itself in Haymond and Sanders, and I think it's mirrored in Swain against Pressley, which interpreted the analogous D.C. provision, and in Boumediene, which is that the saving clause essentially makes sure that federal prisoners weren't disadvantaged by the adoption of this new remedy, they weren't substantively disadvantaged or procedurally disadvantaged."}]},{"t":"case","label":"Bousley v. United States","cite":"523 U.S. 614","y":1998,"id":"1997/96-8516","sc":1,"by":{"0":"9, 35","1":"21, 23, 24","2":"11, 21"},"q":[{"src":"brief","b":1,"text":"so novel that its legal basis [was] not reasonably available","cite":"523 U.S. at 622"},{"src":"brief","b":1,"text":"‘actual innocence’ means factual innocence, not mere legal insufficiency.","cite":"523 U.S. at 623"},{"src":"brief","b":2,"text":"was most surely not a novel one [and] at the time of petitioner’s plea, the Federal Reporters were replete with cases involving challenges","cite":"523 U.S. at 621"},{"src":"brief","b":2,"text":"futility cannot constitute cause if it means simply that a claim was ‘unacceptable to that particular court at that particular time.’","cite":"523 U.S. at 623"},{"src":"argument","who":"Mr. Ortiz","text":"Interestingly, though, all the support the Government has cited for that -- Schlup, McQuiggin, Bousley, and Kuhlmann -- all concern abuse of the writ doctrine."},{"src":"argument","who":"Mr. Feigin","text":"What they are are claims of an unknowing plea, mirroring what happened in Bousley, and they're claims about the jury instructions which sound in the Sixth Amendment."},{"src":"argument","who":"Mr. Feigin","text":"If so, can that person make a -- make the threshold necessary showing of actual factual innocence under Bousley, which can take into account not just the evidence that was presented at trial but all the evidence that could have been presented."}]},{"t":"case","label":"Bunkley v. Florida","cite":"538 U.S. 835","y":2003,"id":"2002/02-8636","sc":1,"by":{"0":"44"}},{"t":"case","label":"Burns v. Wilson","cite":"346 U.S. 137","y":1953,"id":"scdb/1952-107","sc":1,"by":{"0":"31"}},{"t":"case","label":"Castille v. Peoples","cite":"489 U.S. 346","y":1989,"id":"1988/87-1602","sc":1,"by":{"0":"26"},"q":[{"src":"brief","b":0,"text":"whose results have been effectively predetermined.","cite":"489 U.S. 346, 350"}]},{"t":"case","label":"Chazen v. Marske","cite":"938 F.3d 851","y":2019,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/938/851/","by":{"0":"10"},"q":[{"src":"brief","b":0,"text":"‘aimed to fix a ‘glitch’ in § 2255(h)(2),’","cite":"938 F.3d 851, 863"},{"src":"opinion","who":"Justice Jackson, dissenting","text":"appears to have modeled § 2255(h)(2)","cite":"938 F. 3d 851, 863"},{"src":"opinion","who":"Justice Jackson, dissenting","text":"`can raise federal statutory claims in their collateral attacks.'","cite":"938 F. 3d, at 863"},{"src":"argument","who":"Mr. Ortiz","text":"In -- there are arguments on both sides, Your Honor, which you identified in your Chazen opinion while you were sitting on the Seventh Circuit."},{"src":"argument","who":"Mr. Feigin","text":"One thing it might have been thinking, as Justice Barrett pointed out in her separate writing in Chazen, is perhaps it overlooked this, which is fairly realistic because this language was drafted before Bailey against United States, which was kind of a watershed of a statutory interpretation case that applied to a large number of criminal convictions."}]},{"t":"case","label":"Clark v. Suarez Martinez","cite":"543 U.S. 371","y":2005,"id":"2004/03-878","sc":1,"by":{"0":"33"},"q":[{"src":"brief","b":0,"text":"[W]hen deciding which of two plausible statutory constructions to adopt, a court must consider the necessary consequences of its choice. If one of them would raise a multitude of constitutional problems, the other should prevail.","cite":"543 U.S. 371, 380-381"}]},{"t":"case","label":"Clinton v. Goldsmith","cite":"526 U.S. 529","y":1999,"id":"1998/98-347","sc":1,"by":{"0":"31"}},{"t":"case","label":"Corley v. United States","cite":"556 U.S. 303","y":2009,"id":"2008/07-10441","sc":1,"by":{"0":"30"}},{"t":"case","label":"Davis v. United States","cite":"417 U.S. 333","y":1974,"id":"1973/72-1454","sc":1,"by":{"0":"2, 45","1":"passim","2":"4"},"q":[{"src":"brief","b":0,"text":"conviction and punishment for an act the law does not make criminal * * * ‘inherently results in a complete miscarriage of justice’ and ‘presents exceptional circumstances’ that justify collateral relief.","cite":"417 U.S. 333, 346-347"},{"src":"brief","b":0,"text":"conviction and punishment * * * for an act that the law does not make criminal * * * inherently results in a complete miscarriage of justice and present(s) exceptional circumstances that justify collateral relief under § 2255.","cite":"417 U.S. 333, 346-347"},{"src":"brief","b":1,"text":"afford[ed] federal prisoners a remedy identical in scope to federal habeas corpus.","cite":"417 U.S. 333, 343"},{"src":"brief","b":1,"text":"not [been a case] where the law was changed after the time for appeal had expired,","cite":"417 U.S. at 345"},{"src":"brief","b":2,"text":"consideration . . . in the light of * * * Gutknecht,","cite":"417 U.S. at 338"},{"src":"brief","b":2,"text":"[t]he sole issue before the Court * * * is the propriety of the Court of Appeals’ judgment that a change in the law of that Circuit after the petitioner’s conviction may not be successfully asserted by him in a § 2255 proceeding.","cite":"417 U.S. at 341"},{"src":"opinion","who":"Justice Kagan, dissenting","text":"afford federal prisoners a remedy identical in scope to federal habeas corpus.","cite":"417 U. S. 333, 343"}]},{"t":"case","label":"Deckert v. Independence Shares Corps.","cite":"311 U.S. 282","y":1940,"id":"scdb/1940-011","sc":1,"by":{"0":"24"}},{"t":"case","label":"Demore v. Kim","cite":"538 U.S. 510","y":2003,"id":"2002/01-1491","sc":1,"by":{"0":"29"}},{"t":"case","label":"Duckworth v. Serrano","cite":"454 U.S. 1","y":1981,"id":"1981/80-2041","sc":1,"by":{"0":"13"},"q":[{"src":"brief","b":0,"text":"so clearly deficient as to render futile any effort to obtain relief .","cite":"454 U.S. 1, 2"}]},{"t":"case","label":"Duncan v. Walker","cite":"533 U.S. 167","y":2001,"id":"2000/00-121","sc":1,"by":{"0":"16"},"q":[{"src":"brief","b":0,"text":"[T]o construe what Congress has enacted[, a court must] begin, as always, with the language of the statute.","cite":"533 U.S. 167, 172"}]},{"t":"case","label":"Edwards v. United States","cite":"1987 WL 7562","y":1987,"court":"E.D. N.Y.","by":{"0":"32"}},{"t":"case","label":"Edwards v. Vannoy","cite":"141 S. Ct. 1547","y":2021,"id":"2020/19-5807","sc":1,"by":{"0":"11, 14, 35"}},{"t":"case","label":"Egle v. Egle","cite":"715 F.2d 999","y":1983,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/715/999/","by":{"0":"32"}},{"t":"case","label":"Felker v. Turpin","cite":"518 U.S. 651","y":1996,"id":"1995/95-8836","sc":1,"by":{"0":"42","1":"27, 44, 45, 46"},"q":[{"src":"opinion","who":"Opinion of the Court (Justice Thomas)","text":"constitute a modifed res judicata rule,","cite":"518 U. S. 651, 664"},{"src":"opinion","who":"Justice Jackson, dissenting","text":"[A]t the absolute minimum, the Suspension Clause protects the writ `as it existed in 1789'","cite":"518 U. S. 651, 664"},{"src":"argument","who":"Mr. Feigin","text":"We don't think there would be any constitutional problems in these particular circumstances under Felker against Turpin, but even if there were, the easiest way to make sure there's no constitutional problems with the withdrawal of habeas is to keep a residue of habeas where they might inadvertently have missed something --"},{"src":"argument","who":"Mr. Feigin","text":"I think Felker against Turpin is quite clear that when it looked at the parallel limitations in 2244(b), that Congress is free to statutorily alter the abuse of the writ and I think, by analogy, the successive writ doctrines to preclude relief in these circumstances."},{"src":"argument","who":"Ms. Ratner","text":"That's how this Court described it in cases like Felker. And so this isn't a circumstance where there's sort of a body of law Congress forgot about."}]},{"t":"case","label":"Fiore v. White","cite":"531 U.S. 225","y":2001,"id":"1999/98-942","sc":1,"by":{"0":"15, 44","1":"46"},"q":[{"src":"brief","b":0,"text":"the Due Process Clause of the Fourteenth Amendment forbids a State to convict a person of a crime without proving the elements of that crime beyond a reasonable doubt.","cite":"531 U.S. 225, 228-229"}]},{"t":"case","label":"George v. McDonough","cite":"142 S. Ct. 1953","y":2022,"id":"2021/21-234","sc":1,"by":{"0":"19"},"q":[{"src":"brief","b":0,"text":"[w]here Congress employs a term of art obviously transplanted from another legal source, it brings the old soil with it.","cite":"142 S. Ct. 1953, 1959"}]},{"t":"case","label":"Herrera v. Collins","cite":"506 U.S. 390","y":1993,"id":"1992/91-7328","sc":1,"by":{"0":"46"}},{"t":"case","label":"Hillsborough Twp. v. Cromwell","cite":"326 U.S. 620","y":1946,"id":"scdb/1945-084","sc":1,"by":{"0":"24"}},{"t":"case","label":"Lee v. Sanders","cite":"943 F.3d 1145","y":2019,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/943/1145/","by":{"0":"8, 9"},"q":[{"src":"brief","b":0,"text":"§ 2255 is not inadequate or ineffective where a petitioner had any opportunity to present his claim beforehand.","cite":"943 F.3d 1145, 1147"},{"src":"brief","b":0,"text":"Thus, [i]t is the infirmity of the § 2255 remedy itself, not the failure to use it or prevail under it, that is determinative.","cite":"943 F.3d at 1147"}]},{"t":"case","label":"Loughrin v. United States","cite":"573 U.S. 351","y":2014,"id":"2013/13-316","sc":1,"by":{"0":"19, 25"}},{"t":"case","label":"Marino v. Ragen","cite":"332 U.S. 561","y":1947,"id":"scdb/1947-018","sc":1,"by":{"0":"25"}},{"t":"case","label":"McCarthan v. Director of Goodwill Indus.- Suncoast, Inc.","cite":"851 F.3d 1076","y":2017,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/851/1076/","by":{"0":"passim","1":"10, 31, 37, 39, 40, 41"},"q":[{"src":"brief","b":0,"text":"the writ of habeas corpus would not have been available at all to prisoners like Jones [who had been] convicted of crime by a court of competent jurisdiction,","cite":"851 F.3d at 1094"}]},{"t":"case","label":"Montgomery v. Louisiana","cite":"577 U.S. 190","y":2016,"id":"2015/14-280","sc":1,"by":{"0":"35"}},{"t":"case","label":"Morrisey v. Brewer","cite":"408 U.S. 471","y":1972,"id":"1971/71-5103","sc":1,"by":{"0":"31"}},{"t":"case","label":"Pettibone v. United States","cite":"148 U.S. 197","y":1893,"id":"scdb/1892-140","sc":1,"by":{"0":"36-37"}},{"t":"case","label":"Powell v. Texas","cite":"392 U.S. 514","y":1968,"id":"1967/405","sc":1,"by":{"0":"45"}},{"t":"case","label":"Powerex Corp. v. Reliant Energy Servs., Inc.","cite":"551 U.S. 224","y":2007,"id":"2006/05-85","sc":1,"by":{"0":"26"},"q":[{"src":"brief","b":0,"text":"standard principle of statutory construction * * * that identical words and phrases within the same statute should normally be given the same meaning.","cite":"551 U.S. 224, 232"}]},{"t":"case","label":"Preiser v. Rodriguez","cite":"411 U.S. 475","y":1973,"id":"1972/71-1369","sc":1,"by":{"0":"31"}},{"t":"case","label":"Prost v. Anderson","cite":"636 F.3d 578","y":2011,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/636/578/","by":{"0":"passim","1":"11, 15, 16, 41"},"q":[{"src":"brief","b":0,"text":"it is not our place to adopt a test that replaces the balance Congress reached with one of our own liking,","cite":"636 F.3d at 592"},{"src":"brief","b":1,"text":"the question naturally arises: compared to what?","cite":"636 F.3d at 584"}]},{"t":"case","label":"Reed Elsevier, Inc. v. Muchnick","cite":"559 U.S. 154","y":2010,"id":"2009/08-103","sc":1,"by":{"0":"37"},"q":[{"src":"brief","b":0,"text":"court[s’] very power to hear a case.","cite":"559 U.S. 154, 165 n.5"}]},{"t":"case","label":"Rehaif v. United States","cite":"139 S. Ct. 2191","y":2019,"id":"2018/17-9560","sc":1,"by":{"0":"passim","1":"5, 8, 12, 33, 34, 35","2":"21"},"q":[{"src":"brief","b":0,"text":"knew he had the relevant status when he possessed [the gun],","cite":"139 S. Ct. 2191, 2194"},{"src":"brief","b":1,"text":"he knew he belonged to the relevant category of persons barred from possessing a firearm.","cite":"139 S. Ct. at 2200"},{"src":"brief","b":2,"text":"adopted by every single Court of Appeals to address the question.","cite":"139 S. Ct. at 2201"},{"src":"argument","who":"Mr. Feigin","text":"The kinds of Rehaif claims we see on first 2255s aren't these kinds of statutory claims which essentially are claims of actual innocence in merits form."},{"src":"argument","who":"Justice Alito","text":"If it were limited strictly to a situation like Rehaif, fine, everybody could understand that. But are -- are you concerned that every federal prisoner who wants to bring a successive or -- a successive motion is going to claim that this falls within the traditional scope of habeas, and this would be an escape clause that will be invoked again and again and again, and all the district judges are going to have to analyze the traditional scope of -- of habeas and see whether the claim actually falls within that?"},{"src":"argument","who":"Mr. Feigin","text":"So it's different from a sufficiency review, for example, because, under Rehaif, we were never required to introduce evidence of someone's knowledge of their prior felon status."}]},{"t":"case","label":"Rivers v. Roadway Express, Inc.","cite":"511 U.S. 298","y":1994,"id":"1993/92-938","sc":1,"by":{"0":"42","2":"17"},"q":[{"src":"brief","b":0,"text":"is an authoritative statement of what the statute meant before as well as after the decision of the case giving rise to that construction.","cite":"511 U.S. 298, 312-313"}]},{"t":"case","label":"Robinson v. California","cite":"370 U.S. 660","y":1962,"id":"1961/554","sc":1,"by":{"0":"45, 46"}},{"t":"case","label":"Runkle v. United States","cite":"122 U.S. 543","y":1887,"id":"scdb/1886-306","sc":1,"by":{"0":"31"}},{"t":"case","label":"Shinn v. Ramirez","cite":"142 S. Ct. 1718","y":2022,"id":"2021/20-1009","sc":1,"by":{"0":"35"},"q":[{"src":"brief","b":0,"text":"cost[ ] society the right to punish admitted offenders.","cite":"142 S. Ct. at 1731"}]},{"t":"case","label":"Solum v. Helm","cite":"463 U.S. 277","y":1983,"id":"1982/82-492","sc":1,"by":{"0":"15"}},{"t":"case","label":"Spaulding v. Taylor","cite":"336 F.2d 192","y":1964,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/336/192/","by":{"0":"32","2":"4"}},{"t":"case","label":"Taggart v. Lorenzen","cite":"139 S. Ct. 1795","y":2019,"id":"2018/18-489","sc":1,"by":{"0":"19"}},{"t":"case","label":"United States v. Addonizio","cite":"442 U.S. 178","y":1979,"id":"1978/78-156","sc":1,"by":{"0":"37","1":"14, 17, 19, 20, 21"},"q":[{"src":"brief","b":0,"text":"attack convictions and sentences entered by a court without jurisdiction,","cite":"442 U.S. 178, 185"},{"src":"brief","b":1,"text":"to alleviate the burden of habeas corpus petitions filed by federal prisoners in the district of confinement, by providing an equally broad remedy in the more convenient jurisdiction of the sentencing court.","cite":"442 U.S. 178, 185"},{"src":"brief","b":1,"text":"long been settled law that an error that may justify reversal on direct appeal will not necessarily support a collateral attack on a final judgment.","cite":"442 U.S. at 184"}]},{"t":"case","label":"United States v. Hall","cite":"98 U.S. 343","y":1878,"id":"scdb/1878-082","sc":1,"by":{"0":"36","1":"45"}},{"t":"case","label":"United States v. Hayman","cite":"342 U.S. 205","y":1952,"id":"scdb/1951-024","sc":1,"by":{"0":"35, 46","1":"passim","2":"2"},"q":[{"src":"brief","b":1,"text":"a great increase in the number of applications for habeas corpus filed in the federal courts by state and federal prisoners.","cite":"342 U.S. 205, 212"},{"src":"brief","b":1,"text":"far from the scene of the facts, the homes of the witnesses and the records of the sentencing court.","cite":"342 U.S. at 213"},{"src":"brief","b":2,"text":"inadequate or ineffective to test the legality of [the prisoner’s] detention.","cite":"342 U.S. at 216"},{"src":"opinion","who":"Opinion of the Court (Justice Thomas)","text":"was to minimize the diffculties encountered in habeas corpus hearings by affording the same rights in another and more convenient forum.","cite":"342 U. S. 205, 219"},{"src":"opinion","who":"Opinion of the Court (Justice Thomas)","text":"it is not practicable for the prisoner to have his motion determined in the trial court because of his inability to be present at the hearing, or for other reasons.","cite":"342 U. S., at 215, n. 23"},{"src":"opinion","who":"Opinion of the Court (Justice Thomas)","text":"to review each other's proceedings—often without access to the witnesses, the sources of evidence, or other local information that may be critical.","cite":"342 U. S., at 214"}]},{"t":"case","label":"United States v. Jones","cite":"185 Fed. Appx. 541","y":2006,"court":"8th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./185/541/","by":{"0":"7"}},{"t":"case","label":"United States v. Jones","cite":"403 F.3d 604","y":2005,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/403/604/","by":{"0":"7"}},{"t":"case","label":"United States v. Jones","cite":"266 F.3d 804","y":2001,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/266/804/","by":{"0":"5, 6, 26","2":"17, 22, 23"},"q":[{"src":"brief","b":2,"text":"[Jones] knew that he was not supposed to have a gun,","cite":"266 F.3d at 808"}]},{"t":"case","label":"United States v. Kind","cite":"194 F.3d 900","y":1999,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/194/900/","by":{"0":"6"}},{"t":"case","label":"United States v. Lanier","cite":"520 U.S. 259","y":1997,"id":"1996/95-1717","sc":1,"by":{"0":"42"}},{"t":"case","label":"United States v. New Bedford Bridge","cite":"27 F. Cas. 91","y":1847,"court":"D. Mass.","url":"https://www.courtlistener.com/c/F.%20Cas./27/91/","by":{"0":"3, 36"}},{"t":"case","label":"United States ex rel. Dunlap v. Black","cite":"128 U.S. 40","y":1888,"id":"scdb/1888-010","sc":1,"by":{"0":"24"}},{"t":"case","label":"Wisconsin Cent. Ltd. v. United States","cite":"138 S. Ct. 2067","y":2018,"id":"2017/17-530","sc":1,"by":{"0":"16-17"},"q":[{"src":"brief","b":0,"text":"the ordinary meaning at the time Congress enacted the statute","cite":"138 S. Ct. 2067, 2070"}]},{"t":"case","label":"Wooden v. United States","cite":"142 S. Ct. 1063","y":2022,"id":"2021/20-5279","sc":1,"by":{"0":"14, 30"},"q":[{"src":"brief","b":0,"text":"for the most part * * * gives [ § 2255(e)] no work to do,","cite":"142 S. Ct. 1063, 1070"},{"src":"brief","b":0,"text":"wholly superfluous [but] for the most part * * * give[ it] no work to do.","cite":"142 S. Ct. 1063, 1070"}]},{"t":"case","label":"Ysleta Del Sur Pueblo v. Texas","cite":"142 S. Ct. 1929","y":2022,"id":"2021/20-493","sc":1,"by":{"0":"30"},"q":[{"src":"brief","b":0,"text":"must normally seek to construe Congress’s work ‘so that effect is given to all provisions, so that no part will be inoperative or superfluous, void or insignificant.’","cite":"142 S. Ct. 1929, 1939"},{"src":"brief","b":0,"text":"longstanding canon[ ] of statutory construction.","cite":"142 S. Ct. at 1939"}]},{"t":"const","label":"Article I, Section 9, Clause 2","clauses":[["habeas","Suspension Clause (Habeas Corpus)"]],"text":"The Privilege of the Writ of Habeas Corpus shall not be suspended, unless when in Cases of Rebellion or Invasion the public Safety may require it.","by":{"0":"34"}},{"t":"const","label":"Amendment V","clauses":[["grand-jury","Grand Jury Clause"],["double-jeopardy","Double Jeopardy Clause"],["self-incrimination","Self-Incrimination Clause"],["due-process-5","Due Process Clause (Fifth Amendment)"],["takings","Takings Clause"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"0":"43"}},{"t":"const","label":"Amendment VIII","clauses":[["eighth-amendment","Eighth Amendment"]],"text":"Excessive bail shall not be required, nor excessive fines imposed, nor cruel and unusual punishments inflicted.","by":{"0":"45","1":"46"}},{"t":"usc","label":"18 U.S.C. § 922","url":"https://www.law.cornell.edu/uscode/text/18/922","subs":["(a)(6)","(g)","(g)(1)","(a)(6)(1994)","(g)(5)","(g)(5)(A)"],"stext":{"head":"§922. Unlawful acts","paras":[[0,"(a) It shall be unlawful—"],[1,"(1) for any person—"],[2,"(A) except a licensed importer, licensed manufacturer, or licensed dealer, to engage in the business of importing, manufacturing, or dealing in firearms, or in the course of such business to ship, transport, or receive any firearm in interstate or foreign commerce; or"],[2,"(B) except a licensed importer or licensed manufacturer, to engage in the business of importing or manufacturing ammunition, or in the course of such business, to ship, transport, or receive any ammunition in interstate or foreign commerce;"],[1,"(2) for any importer, manufacturer, dealer, or collector licensed under the provisions of this chapter to ship or transport in interstate or foreign commerce any firearm to any person other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, except that—"],[2,"(A) this paragraph and subsection (b)(3) shall not be held to preclude a licensed importer, licensed manufacturer, licensed dealer, or licensed collector from returning a firearm or replacement firearm of the same kind and type to a person from whom it was received; and this paragraph shall not be held to preclude an individual from mailing a firearm owned in compliance with Federal, State, and local law to a licensed importer, licensed manufacturer, licensed dealer, or licensed collector;"],[2,"(B) this paragraph shall not be held to preclude a licensed importer, licensed manufacturer, or licensed dealer from depositing a firearm for conveyance in the mails to any officer, employee, agent, or watchman who, pursuant to the provisions of section 1715 of this title, is eligible to receive through the mails pistols, revolvers, and other firearms capable of being concealed on the person, for use in connection with his official duty; and"],[2,"(C) nothing in this paragraph shall be construed as applying in any manner in the District of Columbia, the Commonwealth of Puerto Rico, or any possession of the United States differently than it would apply if the District of Columbia, the Commonwealth of Puerto Rico, or the possession were in fact a State of the United States;"],[1,"(3) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector to transport into or receive in the State where he resides (or if the person is a corporation or other business entity, the State where it maintains a place of business) any firearm purchased or otherwise obtained by such person outside that State, except that this paragraph (A) shall not preclude any person who lawfully acquires a firearm by bequest or intestate succession in a State other than his State of residence from transporting the firearm into or receiving it in that State, if it is lawful for such person to purchase or possess such firearm in that State, (B) shall not apply to the transportation or receipt of a firearm obtained in conformity with subsection (b)(3) of this section, and (C) shall not apply to the transportation of any firearm acquired in any State prior to the effective date of this chapter;"],[1,"(4) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, to transport in interstate or foreign commerce any destructive device, machinegun (as defined in section 5845 of the Internal Revenue Code of 1986), short-barreled shotgun, or short-barreled rifle, except as specifically authorized by the Attorney General consistent with public safety and necessity;"],[1,"(5) for any person (other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector) to transfer, sell, trade, give, transport, or deliver any firearm to any person (other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector) who the transferor knows or has reasonable cause to believe does not reside in (or if the person is a corporation or other business entity, does not maintain a place of business in) the State in which the transferor resides; except that this paragraph shall not apply to (A) the transfer, transportation, or delivery of a firearm made to carry out a bequest of a firearm to, or an acquisition by intestate succession of a firearm by, a person who is permitted to acquire or possess a firearm under the laws of the State of his residence, and (B) the loan or rental of a firearm to any person for temporary use for lawful sporting purposes;"],[1,"(6) for any person in connection with the acquisition or attempted acquisition of any firearm or ammunition from a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, knowingly to make any false or fictitious oral or written statement or to furnish or exhibit any false, fictitious, or misrepresented identification, intended or likely to deceive such importer, manufacturer, dealer, or collector with respect to any fact material to the lawfulness of the sale or other disposition of such firearm or ammunition under the provisions of this chapter;"],[1,"(7) for any person to manufacture or import armor piercing ammunition, unless—"],[2,"(A) the manufacture of such ammunition is for the use of the United States, any department or agency of the United States, any State, or any department, agency, or political subdivision of a State;"],[2,"(B) the manufacture of such ammunition is for the purpose of exportation; or"],[2,"(C) the manufacture or importation of such ammunition is for the purpose of testing or experimentation and has been authorized by the Attorney General;"],[1,"(8) for any manufacturer or importer to sell or deliver armor piercing ammunition, unless such sale or delivery—"],[2,"(A) is for the use of the United States, any department or agency of the United States, any State, or any department, agency, or political subdivision of a State;"],[2,"(B) is for the purpose of exportation; or"],[2,"(C) is for the purpose of testing or experimentation and has been authorized by the Attorney General; 1"],[1,"(9) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, who does not reside in any State to receive any firearms unless such receipt is for lawful sporting purposes."],[0,"(b) It shall be unlawful for any licensed importer, licensed manufacturer, licensed dealer, or licensed collector to sell or deliver—"],[1,"(1) any firearm or ammunition to any individual who the licensee knows or has reasonable cause to believe is less than eighteen years of age, and, if the firearm, or ammunition is other than a shotgun or rifle, or ammunition for a shotgun or rifle, to any individual who the licensee knows or has reasonable cause to believe is less than twenty-one years of age;"],[1,"(2) any firearm to any person in any State where the purchase or possession by such person of such firearm would be in violation of any State law or any published ordinance applicable at the place of sale, delivery or other disposition, unless the licensee knows or has reasonable cause to believe that the purchase or possession would not be in violation of such State law or such published ordinance;"],[1,"(3) any firearm to any person who the licensee knows or has reasonable cause to believe does not reside in (or if the person is a corporation or other business entity, does not maintain a place of business in) the State in which the licensee's place of business is located, except that this paragraph (A) shall not apply to the sale or delivery of any rifle or shotgun to a resident of a State other than a State in which the licensee's place of business is located if the transferee meets in person with the transferor to accomplish the transfer, and the sale, delivery, and receipt fully comply with the legal conditions of sale in both such States (and any licensed manufacturer, importer or dealer shall be presumed, for purposes of this subparagraph, in the absence of evidence to the contrary, to have had actual knowledge of the State laws and published ordinances of both States), and (B) shall not apply to the loan or rental of a firearm to any person for temporary use for lawful sporting purposes;"],[1,"(4) to any person any destructive device, machinegun (as defined in section 5845 of the Internal Revenue Code of 1986), short-barreled shotgun, or short-barreled rifle, except as specifically authorized by the Attorney General consistent with public safety and necessity; and"],[1,"(5) any firearm or armor-piercing ammunition to any person unless the licensee notes in his records, required to be kept pursuant to section 923 of this chapter, the name, age, and place of residence of such person if the person is an individual, or the identity and principal and local places of business of such person if the person is a corporation or other business entity."],[0,"Paragraphs (1), (2), (3), and (4) of this subsection shall not apply to transactions between licensed importers, licensed manufacturers, licensed dealers, and licensed collectors. Paragraph (4) of this subsection shall not apply to a sale or delivery to any research organization designated by the Attorney General."],[0,"(c) In any case not otherwise prohibited by this chapter, a licensed importer, licensed manufacturer, or licensed dealer may sell a firearm to a person who does not appear in person at the licensee's business premises (other than another licensed importer, manufacturer, or dealer) only if—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/922?type=usc&year=mostrecent&link-type=html"},"by":{"0":"5, passim, 5","1":"3, 4, 35, 5, 33, 42, 3, 4, 33, 33, 33"},"q":[{"src":"brief","b":1,"text":"is illegally or unlawfully in the United States","cite":"18 U.S.C. 922(g)(5)"}]},{"t":"usc","label":"18 U.S.C. § 924","url":"https://www.law.cornell.edu/uscode/text/18/924","subs":["(a)(1)(B)","(a)(2)","(e)","(a)","(e)(1)(1994)","(e)(1)"],"stext":{"head":"§924. Penalties","paras":[[0,"(a)(1) Except as otherwise provided in this subsection, subsection (b), (c), (f), or (p) of this section, or in section 929, whoever—"],[1,"(A) knowingly makes any false statement or representation with respect to the information required by this chapter to be kept in the records of a person licensed under this chapter or in applying for any license or exemption or relief from disability under the provisions of this chapter;"],[1,"(B) knowingly violates subsection (a)(4), (f), (k), or (q) of section 922;"],[1,"(C) knowingly imports or brings into the United States or any possession thereof any firearm or ammunition in violation of section 922(l); or"],[1,"(D) willfully violates any other provision of this chapter,"],[0,"shall be fined under this title, imprisoned not more than five years, or both."],[0,"(2) Whoever knowingly violates subsection (a)(6), (h), (i), (j), or (o) of section 922 shall be fined as provided in this title, imprisoned not more than 10 years, or both."],[0,"(3) Any licensed dealer, licensed importer, licensed manufacturer, or licensed collector who knowingly—"],[1,"(A) makes any false statement or representation with respect to the information required by the provisions of this chapter to be kept in the records of a person licensed under this chapter, or"],[1,"(B) violates subsection (m) of section 922,"],[0,"shall be fined under this title, imprisoned not more than one year, or both."],[0,"(4) Whoever violates section 922(q) shall be fined under this title, imprisoned for not more than 5 years, or both. Notwithstanding any other provision of law, the term of imprisonment imposed under this paragraph shall not run concurrently with any other term of imprisonment imposed under any other provision of law. Except for the authorization of a term of imprisonment of not more than 5 years made in this paragraph, for the purpose of any other law a violation of section 922(q) shall be deemed to be a misdemeanor."],[0,"(5) Whoever knowingly violates subsection (s) or (t) of section 922 shall be fined under this title, imprisoned for not more than 1 year, or both."],[0,"(6)(A)(i) A juvenile who violates section 922(x) shall be fined under this title, imprisoned not more than 1 year, or both, except that a juvenile described in clause (ii) shall be sentenced to probation on appropriate conditions and shall not be incarcerated unless the juvenile fails to comply with a condition of probation."],[0,"(ii) A juvenile is described in this clause if—"],[1,"(I) the offense of which the juvenile is charged is possession of a handgun or ammunition in violation of section 922(x)(2); and"],[1,"(II) the juvenile has not been convicted in any court of an offense (including an offense under section 922(x) or a similar State law, but not including any other offense consisting of conduct that if engaged in by an adult would not constitute an offense) or adjudicated as a juvenile delinquent for conduct that if engaged in by an adult would constitute an offense."],[0,"(B) A person other than a juvenile who knowingly violates section 922(x)—"],[1,"(i) shall be fined under this title, imprisoned not more than 1 year, or both; and"],[1,"(ii) if the person sold, delivered, or otherwise transferred a handgun or ammunition to a juvenile knowing or having reasonable cause to know that the juvenile intended to carry or otherwise possess or discharge or otherwise use the handgun or ammunition in the commission of a crime of violence, shall be fined under this title, imprisoned not more than 10 years, or both."],[0,"(7) Whoever knowingly violates section 931 shall be fined under this title, imprisoned not more than 3 years, or both."],[0,"(8) Whoever knowingly violates subsection (d) or (g) of section 922 shall be fined under this title, imprisoned for not more than 15 years, or both."],[0,"(b) Whoever, with intent to commit therewith an offense punishable by imprisonment for a term exceeding one year, or with knowledge or reasonable cause to believe that an offense punishable by imprisonment for a term exceeding one year is to be committed therewith, ships, transports, or receives a firearm or any ammunition in interstate or foreign commerce shall be fined under this title, or imprisoned not more than ten years, or both."],[0,"(c)(1)(A) Except to the extent that a greater minimum sentence is otherwise provided by this subsection or by any other provision of law, any person who, during and in relation to any crime of violence or drug trafficking crime (including a crime of violence or drug trafficking crime that provides for an enhanced punishment if committed by the use of a deadly or dangerous weapon or device) for which the person may be prosecuted in a court of the United States, uses or carries a firearm, or who, in furtherance of any such crime, possesses a firearm, shall, in addition to the punishment provided for such crime of violence or drug trafficking crime—"],[1,"(i) be sentenced to a term of imprisonment of not less than 5 years;"],[1,"(ii) if the firearm is brandished, be sentenced to a term of imprisonment of not less than 7 years; and"],[1,"(iii) if the firearm is discharged, be sentenced to a term of imprisonment of not less than 10 years."],[0,"(B) If the firearm possessed by a person convicted of a violation of this subsection—"],[1,"(i) is a short-barreled rifle, short-barreled shotgun, or semiautomatic assault weapon, the person shall be sentenced to a term of imprisonment of not less than 10 years; or"],[1,"(ii) is a machinegun or a destructive device, or is equipped with a firearm silencer or firearm muffler, the person shall be sentenced to a term of imprisonment of not less than 30 years."],[0,"(C) In the case of a violation of this subsection that occurs after a prior conviction under this subsection has become final, the person shall—"],[1,"(i) be sentenced to a term of imprisonment of not less than 25 years; and"],[1,"(ii) if the firearm involved is a machinegun or a destructive device, or is equipped with a firearm silencer or firearm muffler, be sentenced to imprisonment for life."],[0,"(D) Notwithstanding any other provision of law—"],[1,"(i) a court shall not place on probation any person convicted of a violation of this subsection; and"],[1,"(ii) no term of imprisonment imposed on a person under this subsection shall run concurrently with any other term of imprisonment imposed on the person, including any term of imprisonment imposed for the crime of violence or drug trafficking crime during which the firearm was used, carried, or possessed."],[0,"(2) For purposes of this subsection, the term \"drug trafficking crime\" means any felony punishable under the Controlled Substances Act (21 U.S.C. 801 et seq.), the Controlled Substances Import and Export Act (21 U.S.C. 951 et seq.), or chapter 705 of title 46."],[0,"(3) For purposes of this subsection the term \"crime of violence\" means an offense that is a felony and—"],[1,"(A) has as an element the use, attempted use, or threatened use of physical force against the person or property of another, or"],[1,"(B) that by its nature, involves a substantial risk that physical force against the person or property of another may be used in the course of committing the offense."],[0,"(4) For purposes of this subsection, the term \"brandish\" means, with respect to a firearm, to display all or part of the firearm, or otherwise make the presence of the firearm known to another person, in order to intimidate that person, regardless of whether the firearm is directly visible to that person."],[0,"(5) Except to the extent that a greater minimum sentence is otherwise provided under this subsection, or by any other provision of law, any person who, during and in relation to any crime of violence or drug trafficking crime (including a crime of violence or drug trafficking crime that provides for an enhanced punishment if committed by the use of a deadly or dangerous weapon or device) for which the person may be prosecuted in a court of the United States, uses or carries armor piercing ammunition, or who, in furtherance of any such crime, possesses armor piercing ammunition, shall, in addition to the punishment provided for such crime of violence or drug trafficking crime or conviction under this section—"],[1,"(A) be sentenced to a term of imprisonment of not less than 15 years; and"],[1,"(B) if death results from the use of such ammunition—"],[2,"(i) if the killing is murder (as defined in section 1111), be punished by death or sentenced to a term of imprisonment for any term of years or for life; and"],[2,"(ii) if the killing is manslaughter (as defined in section 1112), be punished as provided in section 1112."],[0,"(d)(1) Any firearm or ammunition involved in or used in any knowing violation of subsection (a)(4), (a)(6), (f), (g), (h), (i), (j), or (k) of section 922, or knowing importation or bringing into the United States or any possession thereof any firearm or ammunition in violation of section 922(l), or knowing violation of section 924, 932, or 933, or willful violation of any other provision of this chapter or any rule or regulation promulgated thereunder, or any violation of any other criminal law of the United States, or any firearm or ammunition intended to be used in any offense referred to in paragraph (3) of this subsection, where such intent is demonstrated by clear and convincing evidence, shall be subject to seizure and forfeiture, and all provisions of the Internal Revenue Code of 1986 relating to the seizure, forfeiture, and disposition of firearms, as defined in section 5845(a) of that Code, shall, so far as applicable, extend to seizures and forfeitures under the provisions of this chapter: Provided, That upon acquittal of the owner or possessor, or dismissal of the charges against him other than upon motion of the Government prior to trial, or lapse of or court termination of the restraining order to which he is subject, the seized or relinquished firearms or ammunition shall be returned forthwith to the owner or possessor or to a person delegated by the owner or possessor unless the return of the firearms or ammunition would place the owner or possessor or his delegate in violation of law. Any action or proceeding for the forfeiture of firearms or ammunition shall be commenced within one hundred and twenty days of such seizure."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/924?type=usc&year=mostrecent&link-type=html"},"by":{"0":"5, 37, 5","1":"42, 33, 4, 3, 4, 33"},"q":[{"src":"opinion","who":"Opinion of the Court (Justice Thomas)","text":"during and in relation to any crime of violence or drug traffcking crime,","cite":"18 U. S. C. § 924(c)(1)"}]},{"t":"usc","label":"28 U.S.C. § 384","url":"https://www.law.cornell.edu/uscode/text/28/384","by":{"0":"28"}},{"t":"usc","label":"28 U.S.C. § 1405","url":"https://www.law.cornell.edu/uscode/text/28/1405","by":{"0":"33"}},{"t":"usc","label":"28 U.S.C. § 2241","url":"https://www.law.cornell.edu/uscode/text/28/2241","subs":["(c)"],"stext":{"head":"§2241. Power to grant writ","paras":[[0,"(a) Writs of habeas corpus may be granted by the Supreme Court, any justice thereof, the district courts and any circuit judge within their respective jurisdictions. The order of a circuit judge shall be entered in the records of the district court of the district wherein the restraint complained of is had."],[0,"(b) The Supreme Court, any justice thereof, and any circuit judge may decline to entertain an application for a writ of habeas corpus and may transfer the application for hearing and determination to the district court having jurisdiction to entertain it."],[0,"(c) The writ of habeas corpus shall not extend to a prisoner unless—"],[1,"(1) He is in custody under or by color of the authority of the United States or is committed for trial before some court thereof; or"],[1,"(2) He is in custody for an act done or omitted in pursuance of an Act of Congress, or an order, process, judgment or decree of a court or judge of the United States; or"],[1,"(3) He is in custody in violation of the Constitution or laws or treaties of the United States; or"],[1,"(4) He, being a citizen of a foreign state and domiciled therein is in custody for an act done or omitted under any alleged right, title, authority, privilege, protection, or exemption claimed under the commission, order or sanction of any foreign state, or under color thereof, the validity and effect of which depend upon the law of nations; or"],[1,"(5) It is necessary to bring him into court to testify or for trial."],[0,"(d) Where an application for a writ of habeas corpus is made by a person in custody under the judgment and sentence of a State court of a State which contains two or more Federal judicial districts, the application may be filed in the district court for the district wherein such person is in custody or in the district court for the district within which the State court was held which convicted and sentenced him and each of such district courts shall have concurrent jurisdiction to entertain the application. The district court for the district wherein such an application is filed in the exercise of its discretion and in furtherance of justice may transfer the application to the other district court for hearing and determination."],[0,"(e)(1) No court, justice, or judge shall have jurisdiction to hear or consider an application for a writ of habeas corpus filed by or on behalf of an alien detained by the United States who has been determined by the United States to have been properly detained as an enemy combatant or is awaiting such determination."],[0,"(2) Except as provided in paragraphs (2) and (3) of section 1005(e) of the Detainee Treatment Act of 2005 (10 U.S.C. 801 note), no court, justice, or judge shall have jurisdiction to hear or consider any other action against the United States or its agents relating to any aspect of the detention, transfer, treatment, trial, or conditions of confinement of an alien who is or was detained by the United States and has been determined by the United States to have been properly detained as an enemy combatant or is awaiting such determination."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2241?type=usc&year=mostrecent&link-type=html"},"by":{"0":"passim, 31","1":"16","2":"passim"}},{"t":"usc","label":"28 U.S.C. § 2254","url":"https://www.law.cornell.edu/uscode/text/28/2254","subs":["(b)","(b)(1)(B)(ii)"],"stext":{"head":"§2254. State custody; remedies in Federal courts","paras":[[0,"(a) The Supreme Court, a Justice thereof, a circuit judge, or a district court shall entertain an application for a writ of habeas corpus in behalf of a person in custody pursuant to the judgment of a State court only on the ground that he is in custody in violation of the Constitution or laws or treaties of the United States."],[0,"(b)(1) An application for a writ of habeas corpus on behalf of a person in custody pursuant to the judgment of a State court shall not be granted unless it appears that—"],[1,"(A) the applicant has exhausted the remedies available in the courts of the State; or"],[1,"(B)(i) there is an absence of available State corrective process; or"],[1,"(ii) circumstances exist that render such process ineffective to protect the rights of the applicant."],[0,"(2) An application for a writ of habeas corpus may be denied on the merits, notwithstanding the failure of the applicant to exhaust the remedies available in the courts of the State."],[0,"(3) A State shall not be deemed to have waived the exhaustion requirement or be estopped from reliance upon the requirement unless the State, through counsel, expressly waives the requirement."],[0,"(c) An applicant shall not be deemed to have exhausted the remedies available in the courts of the State, within the meaning of this section, if he has the right under the law of the State to raise, by any available procedure, the question presented."],[0,"(d) An application for a writ of habeas corpus on behalf of a person in custody pursuant to the judgment of a State court shall not be granted with respect to any claim that was adjudicated on the merits in State court proceedings unless the adjudication of the claim—"],[1,"(1) resulted in a decision that was contrary to, or involved an unreasonable application of, clearly established Federal law, as determined by the Supreme Court of the United States; or"],[1,"(2) resulted in a decision that was based on an unreasonable determination of the facts in light of the evidence presented in the State court proceeding."],[0,"(e)(1) In a proceeding instituted by an application for a writ of habeas corpus by a person in custody pursuant to the judgment of a State court, a determination of a factual issue made by a State court shall be presumed to be correct. The applicant shall have the burden of rebutting the presumption of correctness by clear and convincing evidence."],[0,"(2) If the applicant has failed to develop the factual basis of a claim in State court proceedings, the court shall not hold an evidentiary hearing on the claim unless the applicant shows that—"],[1,"(A) the claim relies on—"],[2,"(i) a new rule of constitutional law, made retroactive to cases on collateral review by the Supreme Court, that was previously unavailable; or"],[2,"(ii) a factual predicate that could not have been previously discovered through the exercise of due diligence; and"],[1,"(B) the facts underlying the claim would be sufficient to establish by clear and convincing evidence that but for constitutional error, no reasonable factfinder would have found the applicant guilty of the underlying offense."],[0,"(f) If the applicant challenges the sufficiency of the evidence adduced in such State court proceeding to support the State court's determination of a factual issue made therein, the applicant, if able, shall produce that part of the record pertinent to a determination of the sufficiency of the evidence to support such determination. If the applicant, because of indigency or other reason is unable to produce such part of the record, then the State shall produce such part of the record and the Federal court shall direct the State to do so by order directed to an appropriate State official. If the State cannot provide such pertinent part of the record, then the court shall determine under the existing facts and circumstances what weight shall be given to the State court's factual determination."],[0,"(g) A copy of the official records of the State court, duly certified by the clerk of such court to be a true and correct copy of a finding, judicial opinion, or other reliable written indicia showing such a factual determination by the State court shall be admissible in the Federal court proceeding."],[0,"(h) Except as provided in section 408 of the Controlled Substances Act, in all proceedings brought under this section, and any subsequent proceedings on review, the court may appoint counsel for an applicant who is or becomes financially unable to afford counsel, except as provided by a rule promulgated by the Supreme Court pursuant to statutory authority. Appointment of counsel under this section shall be governed by section 3006A of title 18."],[0,"(i) The ineffectiveness or incompetence of counsel during Federal or State collateral post-conviction proceedings shall not be a ground for relief in a proceeding arising under section 2254."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2254?type=usc&year=mostrecent&link-type=html"},"by":{"0":"26, 26"},"q":[{"src":"brief","b":0,"text":"ineffective to protect the rights of","cite":"28 U.S.C. § 2254(b)(1)(B)(ii)"}]},{"t":"usc","label":"28 U.S.C. § 2255","url":"https://www.law.cornell.edu/uscode/text/28/2255","subs":["(a)","(e)","(h)","(h)(2)","(h)(1)"],"stext":{"head":"§2255. Federal custody; remedies on motion attacking sentence","paras":[[0,"(a) A prisoner in custody under sentence of a court established by Act of Congress claiming the right to be released upon the ground that the sentence was imposed in violation of the Constitution or laws of the United States, or that the court was without jurisdiction to impose such sentence, or that the sentence was in excess of the maximum authorized by law, or is otherwise subject to collateral attack, may move the court which imposed the sentence to vacate, set aside or correct the sentence."],[0,"(b) Unless the motion and the files and records of the case conclusively show that the prisoner is entitled to no relief, the court shall cause notice thereof to be served upon the United States attorney, grant a prompt hearing thereon, determine the issues and make findings of fact and conclusions of law with respect thereto. If the court finds that the judgment was rendered without jurisdiction, or that the sentence imposed was not authorized by law or otherwise open to collateral attack, or that there has been such a denial or infringement of the constitutional rights of the prisoner as to render the judgment vulnerable to collateral attack, the court shall vacate and set the judgment aside and shall discharge the prisoner or resentence him or grant a new trial or correct the sentence as may appear appropriate."],[0,"(c) A court may entertain and determine such motion without requiring the production of the prisoner at the hearing."],[0,"(d) An appeal may be taken to the court of appeals from the order entered on the motion as from a final judgment on application for a writ of habeas corpus."],[0,"(e) An application for a writ of habeas corpus in behalf of a prisoner who is authorized to apply for relief by motion pursuant to this section, shall not be entertained if it appears that the applicant has failed to apply for relief, by motion, to the court which sentenced him, or that such court has denied him relief, unless it also appears that the remedy by motion is inadequate or ineffective to test the legality of his detention."],[0,"(f) A 1-year period of limitation shall apply to a motion under this section. The limitation period shall run from the latest of—"],[1,"(1) the date on which the judgment of conviction becomes final;"],[1,"(2) the date on which the impediment to making a motion created by governmental action in violation of the Constitution or laws of the United States is removed, if the movant was prevented from making a motion by such governmental action;"],[1,"(3) the date on which the right asserted was initially recognized by the Supreme Court, if that right has been newly recognized by the Supreme Court and made retroactively applicable to cases on collateral review; or"],[1,"(4) the date on which the facts supporting the claim or claims presented could have been discovered through the exercise of due diligence."],[0,"(g) Except as provided in section 408 of the Controlled Substances Act, in all proceedings brought under this section, and any subsequent proceedings on review, the court may appoint counsel, except as provided by a rule promulgated by the Supreme Court pursuant to statutory authority. Appointment of counsel under this section shall be governed by section 3006A of title 18."],[0,"(h) A second or successive motion must be certified as provided in section 2244 by a panel of the appropriate court of appeals to contain—"],[1,"(1) newly discovered evidence that, if proven and viewed in light of the evidence as a whole, would be sufficient to establish by clear and convincing evidence that no reasonable factfinder would have found the movant guilty of the offense; or"],[1,"(2) a new rule of constitutional law, made retroactive to cases on collateral review by the Supreme Court, that was previously unavailable."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2255?type=usc&year=mostrecent&link-type=html"},"by":{"0":"passim, passim, passim, passim, passim","1":"16, 16, 16, 16, 16, 16","2":"passim, 5, 6, 7, passim, 10"},"q":[{"src":"brief","b":0,"text":"the legality of * * * detention.","cite":"28 U.S.C. § 2255(e)"},{"src":"brief","b":0,"text":"upon the ground that the sentence was imposed in violation of the Constitution or laws of the United States, or that the court was without jurisdiction to impose such sentence, or that the sentence was in excess of the maximum authorized by law, or is otherwise subject to collateral attack.","cite":"28 U.S.C. § 2255(a)"},{"src":"brief","b":1,"text":"a new rule of constitutional law, made retroactive to cases on collateral review by the Supreme Court, that was previously unavailable.","cite":"28 U.S.C. 2255(h)"},{"src":"brief","b":1,"text":"is inadequate or ineffective to test the legality of [the prisoner’s] detention.","cite":"28 U.S.C. 2255(e)"},{"src":"brief","b":2,"text":"authorized to apply for relief by motion pursuant to [Section 2255],","cite":"28 U.S.C. § 2255(e)"},{"src":"brief","b":2,"text":"prisoner[s] in custody under sentence of a court established by Act of Congress.","cite":"28 U.S.C. § 2255(a)"},{"src":"argument","who":"Mr. Ortiz","text":"And so, as Congress -- Congress originally intended in 1948 that as the contours of Section 2255 changed, it would never be placed under constitutional pressure because 2255 would always allow this out."},{"src":"argument","who":"Mr. Feigin","text":"So, Your Honor, you look at federal habeas corpus now, and the body of federal habeas corpus now can be informed by Section 2255 itself and its limits and the limits that Congress has imposed on state prisoners through 2244."},{"src":"argument","who":"Mr. Feigin","text":"And it can be informed by Section 2255, particularly in its provisions like 2255(h) or its statutes of -- statute of limitations that are also mirrored in state habeas, because that gives us a very clear indication that habeas, as it stands today, does not allow those kinds of claims, the kinds of constitutional and factual claims that I still think my friend the Petitioner's approach might in theory allow."}]},{"t":"law","label":"An Act to Implement the Recommendations of the Federal Courts Study Committee, and for Other Purposes, Pub. L. No. 102-572","url":"https://www.govinfo.gov/link/statute/106/4506","by":{"0":"31-32"}},{"t":"law","label":"An Act to Provide for the Admission of the State of Alaska Into the Union, Pub. L. No. 85-508","url":"https://www.govinfo.gov/link/statute/72/339","by":{"0":"32"}},{"t":"law","label":"An Act to Provide for the Admission of the State of Hawaii into the Union, Pub. L. No. 86-3","url":"https://www.govinfo.gov/link/statute/73/4","by":{"0":"32"}},{"t":"law","label":"and Other Provisions: Antiterrorism and Effective Death Penalty Act, Pub. L. No. 104-132","url":"https://www.govinfo.gov/link/plaw/104/public/132","by":{"0":"4","1":"7, 25"}},{"t":"rule","label":"Fed. R. Civ. P. 2","url":"https://www.law.cornell.edu/rules/frcp/rule_2","by":{"0":"24"}},{"t":"case","label":"Brown v. Davenport","cite":"142 S. Ct. 1510","y":2022,"id":"2021/20-826","sc":1,"by":{"1":"20, 23, 25"}},{"t":"case","label":"Calderon v. Thompson","cite":"523 U.S. 538","y":1998,"id":"1997/97-215","sc":1,"by":{"1":"30"},"q":[{"src":"brief","b":1,"text":"objective in content, ‘well-defined in the case law,’ and ‘familiar to federal courts.’","cite":"523 U.S. 538, 559"}]},{"t":"case","label":"Coleman v. Thompson","cite":"501 U.S. 722","y":1991,"id":"1990/89-7662","sc":1,"by":{"1":"23"},"q":[{"src":"argument","who":"Mr. Feigin","text":"The only kinds of statutory claims that you could possibly ever bring under successive and abuse of the writ doctrine are going to be claims based on intervening decision of this Court, and that's going to be a set of claims, but that gets to my second reason, which is, under both successive habeas petition doctrine under Coleman or abuse of the writ doctrine under McCleskey, for example, you will see that that requires -- is going to require a showing of actual innocence that's going to be very hard to make and can get knocked out pretty easily at the threshold."}]},{"t":"case","label":"Dietz v. Bouldin","cite":"579 U.S. 40","y":2016,"id":"2015/15-458","sc":1,"by":{"1":"41"}},{"t":"case","label":"Dretke v. Haley","cite":"541 U.S. 386","y":2004,"id":"2003/02-1824","sc":1,"by":{"1":"30, 31"},"q":[{"src":"brief","b":1,"text":"finality * * * and the orderly administration of justice,","cite":"541 U.S. 386, 388"}]},{"t":"case","label":"Estelle v. McGuire","cite":"502 U.S. 62","y":1991,"id":"1991/90-1074","sc":1,"by":{"1":"28"},"q":[{"src":"opinion","who":"Opinion of the Court (Justice Thomas)","text":"`federal habeas corpus relief does not lie for errors of state law.'","cite":"502 U. S. 62, 67"}]},{"t":"case","label":"Greer v. United States","cite":"141 S. Ct. 2090","y":2021,"id":"2020/19-8709","sc":1,"by":{"1":"32, 33, 34"},"q":[{"src":"brief","b":1,"text":"‘will be difficult for most convicted felons for one simple reason: Convicted felons typically know they’re convicted felons.’","cite":"141 S. Ct. at 2098"}]},{"t":"case","label":"Gutknecht v. United States","cite":"396 U.S. 295","y":1970,"id":"1969/71","sc":1,"by":{"1":"20","2":"18"},"q":[{"src":"argument","who":"Mr. Ortiz","text":"In that case, Your Honor, the change by -- of law by this Court, the Gutknecht case, happened while the Davis case was on direct appeal in the Ninth Circuit, and then the Ninth Circuit remanded the case to the district court and the case came back up again."}]},{"t":"case","label":"Hamm v. City of Rock Hill","cite":"379 U.S. 306","y":1964,"id":"1964/2","sc":1,"by":{"1":"28"}},{"t":"case","label":"Hill v. United States","cite":"368 U.S. 424","y":1962,"id":"1961/68","sc":1,"by":{"1":"17, 20"},"q":[{"src":"brief","b":1,"text":"fundamental defect which inherently results in a complete miscarriage of justice.","cite":"368 U.S. at 428"}]},{"t":"case","label":"Holland v. Florida","cite":"560 U.S. 631","y":2010,"id":"2009/09-5327","sc":1,"by":{"1":"29"},"q":[{"src":"brief","b":1,"text":"counsel[] hesitancy before interpreting AEDPA’s statutory silence as indicating a congressional intent to close courthouse doors that a strong eq- uitable claim would ordinarily keep open.","cite":"560 U.S. 631, 649"},{"src":"argument","who":"Mr. Feigin","text":"It's just that as this Court has stated in multiple recent cases, like McQuiggin and Holland, it requires something of a -- a clear statement or a bright light indicator to withdraw the federal habeas remedy."},{"src":"argument","who":"Ms. Ratner","text":"What the Court was concerned about in cases like McQuiggin and Holland is sort of that Congress had forgotten about this equitable doctrine -- doctrine."}]},{"t":"case","label":"INS v. St. Cyr","cite":"533 U.S. 289","y":2001,"id":"2000/00-767","sc":1,"by":{"1":"44"},"q":[{"src":"opinion","who":"Justice Jackson, dissenting","text":"[i]mplications from statutory text or legislative history are not suffcient to repeal habeas jurisdiction; instead, Congress must articulate specifc and unambiguous statutory directives to effect a repeal.","cite":"533 U. S., at 299"}]},{"t":"case","label":"Kemp v. United States","cite":"142 S. Ct. 1856","y":2022,"id":"2021/21-5726","sc":1,"by":{"1":"40"}},{"t":"case","label":"Kuhlmann v. Wilson","cite":"477 U.S. 436","y":1986,"id":"1985/84-1479","sc":1,"by":{"1":"23"},"q":[{"src":"brief","b":1,"text":"the historic function of habeas corpus to provide relief from unjust incarceration.","cite":"477 U.S. at 452"},{"src":"argument","who":"Mr. Ortiz","text":"Interestingly, though, all the support the Government has cited for that -- Schlup, McQuiggin, Bousley, and Kuhlmann -- all concern abuse of the writ doctrine."}]},{"t":"case","label":"Martinez v. Ryan","cite":"566 U.S. 1","y":2012,"id":"2011/10-1001","sc":1,"by":{"1":"23"}},{"t":"case","label":"McCleskey v. Zant","cite":"499 U.S. 467","y":1991,"id":"1990/89-7024","sc":1,"by":{"1":"23, 29","2":"20"},"q":[{"src":"argument","who":"Mr. Ortiz","text":"Your Honor, Congress in that took the -- we believe that what Congress did there is it took the language from this -- this Court had developed in McCleskey versus Zant on actual innocence and basically codified it."},{"src":"argument","who":"Mr. Feigin","text":"The only kinds of statutory claims that you could possibly ever bring under successive and abuse of the writ doctrine are going to be claims based on intervening decision of this Court, and that's going to be a set of claims, but that gets to my second reason, which is, under both successive habeas petition doctrine under Coleman or abuse of the writ doctrine under McCleskey, for example, you will see that that requires -- is going to require a showing of actual innocence that's going to be very hard to make and can get knocked out pretty easily at the threshold."}]},{"t":"case","label":"McQuiggin v. Perkins","cite":"569 U.S. 383","y":2013,"id":"2012/12-126","sc":1,"by":{"1":"passim"},"q":[{"src":"brief","b":1,"text":"[e]quitable principles have traditionally governed the substantive law of habeas corpus.","cite":"569 U.S. at 397"},{"src":"brief","b":1,"text":"it is more likely than not that no reasonable juror would have convicted him","cite":"569 U.S. at 387, 399"},{"src":"opinion","who":"Justice Jackson, dissenting","text":"`the societal interests in fnality, comity, and conservation of scarce judicial resources.'","cite":"569 U. S. 383, 393"},{"src":"argument","who":"Mr. Ortiz","text":"As I said in the opening, there's no real indication, let alone by the clear statement that this Court has required in cases like McQuiggin and St."},{"src":"argument","who":"Mr. Ortiz","text":"Interestingly, though, all the support the Government has cited for that -- Schlup, McQuiggin, Bousley, and Kuhlmann -- all concern abuse of the writ doctrine."},{"src":"argument","who":"Mr. Feigin","text":"It's just that as this Court has stated in multiple recent cases, like McQuiggin and Holland, it requires something of a -- a clear statement or a bright light indicator to withdraw the federal habeas remedy."}]},{"t":"case","label":"Musacchio v. United States","cite":"577 U.S. 237","y":2016,"id":"2015/14-1095","sc":1,"by":{"1":"21"}},{"t":"case","label":"Neder v. United States","cite":"527 U.S. 1","y":1999,"id":"1998/97-1985","sc":1,"by":{"1":"21"}},{"t":"case","label":"Nichols v. United States","cite":"578 U.S. 104","y":2016,"id":"2015/15-5238","sc":1,"by":{"1":"15, 37"}},{"t":"case","label":"Rumsfeld v. Padilla","cite":"542 U.S. 426","y":2004,"id":"2003/03-1027","sc":1,"by":{"1":"13"}},{"t":"case","label":"Sanders v. United States","cite":"373 U.S. 1","y":1963,"id":"1962/202","sc":1,"by":{"1":"17, 29, 38"}},{"t":"case","label":"Schlup v. Delo","cite":"513 U.S. 298","y":1995,"id":"1994/93-7901","sc":1,"by":{"1":"24, 34, 35"},"q":[{"src":"brief","b":1,"text":"the imperative of correcting a fundamentally unjust incarceration.","cite":"513 U.S. 298, 320-321"},{"src":"brief","b":1,"text":"show that it is more likely than not that no reasonable juror would have convicted him","cite":"513 U.S. at 322, 327"},{"src":"argument","who":"Mr. Ortiz","text":"Interestingly, though, all the support the Government has cited for that -- Schlup, McQuiggin, Bousley, and Kuhlmann -- all concern abuse of the writ doctrine."},{"src":"argument","who":"Mr. Feigin","text":"And then you've got the point that I was discussing with Justice Jackson, which is that this -- these kinds of claims aren't really the kinds of claims where you care very much whether they go to the sentencing court or not because, as this Court made clear in Bousley and House and Schlup, they involve a lot of extra-record evidence that, you know, under Rule 11, for example, with plea negotiations, the sentencing courts never seen."}]},{"t":"case","label":"Sunal v. Large","cite":"332 U.S. 174","y":1947,"id":"scdb/1946-132","sc":1,"by":{"1":"21, 22, 31"}},{"t":"case","label":"Swain v. Pressley","cite":"430 U.S. 372","y":1977,"id":"1976/75-811","sc":1,"by":{"1":"18"},"q":[{"src":"argument","who":"Mr. Feigin","text":"But I think the bottom line, Your Honor, is the way we're interpreting it now is the way that the Court actually interpreted it itself in Haymond and Sanders, and I think it's mirrored in Swain against Pressley, which interpreted the analogous D.C. provision, and in Boumediene, which is that the saving clause essentially makes sure that federal prisoners weren't disadvantaged by the adoption of this new remedy, they weren't substantively disadvantaged or procedurally disadvantaged."},{"src":"argument","who":"Ms. Ratner","text":"That's the commonsense approach that this Court took in Haymond and Swain, and that's how the saving clause applied for nearly 50 years from 1948 to 1996."},{"src":"argument","who":"Ms. Ratner","text":"The same is true in Swain. In fact, I don't even think Swain would survive the Government's theory because there was a difference between habeas and sentencing court there, but the analysis was the same."}]},{"t":"case","label":"Taylor v. Gilkey","cite":"314 F.3d 832","y":2002,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/314/832/","by":{"1":"41, 42"},"q":[{"src":"brief","b":1,"text":"focus on procedures rather than outcomes.","cite":"314 F.3d 832, 835"}]},{"t":"case","label":"Triestman v. United States","cite":"124 F.3d 361","y":1997,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/124/361/","by":{"1":"10","2":"3"}},{"t":"case","label":"United States v. Cotton","cite":"535 U.S. 625","y":2002,"id":"2001/01-687","sc":1,"by":{"1":"45"}},{"t":"case","label":"United States v. Jones","cite":"275 F.3d 673","y":2001,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/275/673/","by":{"1":"4"}},{"t":"case","label":"United States v. Throckmorton","cite":"98 U.S. 61","y":1878,"id":"scdb/1878-047","sc":1,"by":{"1":"43"}},{"t":"case","label":"United States v. Williams","cite":"341 U.S. 58","y":1951,"id":"scdb/1950-062","sc":1,"by":{"1":"45"},"q":[{"src":"brief","b":1,"text":"oust [the trial] court of jurisdiction.","cite":"341 U.S. 58, 68"}]},{"t":"const","label":"Amendment XIV","clauses":[["due-process-14","Due Process Clause (Fourteenth Amendment)"]],"by":{"1":"46"}},{"t":"usc","label":"1 U.S.C. § 1","url":"https://www.law.cornell.edu/uscode/text/1/1","by":{"1":"15, 37"}},{"t":"usc","label":"28 U.S.C. § 2244","url":"https://www.law.cornell.edu/uscode/text/28/2244","subs":["(b)(2)","(b)(2)(A)","(b)(2)(B)"],"stext":{"head":"§2244. Finality of determination","paras":[[0,"(a) No circuit or district judge shall be required to entertain an application for a writ of habeas corpus to inquire into the detention of a person pursuant to a judgment of a court of the United States if it appears that the legality of such detention has been determined by a judge or court of the United States on a prior application for a writ of habeas corpus, except as provided in section 2255."],[0,"(b)(1) A claim presented in a second or successive habeas corpus application under section 2254 that was presented in a prior application shall be dismissed."],[0,"(2) A claim presented in a second or successive habeas corpus application under section 2254 that was not presented in a prior application shall be dismissed unless—"],[1,"(A) the applicant shows that the claim relies on a new rule of constitutional law, made retroactive to cases on collateral review by the Supreme Court, that was previously unavailable; or"],[1,"(B)(i) the factual predicate for the claim could not have been discovered previously through the exercise of due diligence; and"],[1,"(ii) the facts underlying the claim, if proven and viewed in light of the evidence as a whole, would be sufficient to establish by clear and convincing evidence that, but for constitutional error, no reasonable factfinder would have found the applicant guilty of the underlying offense."],[0,"(3)(A) Before a second or successive application permitted by this section is filed in the district court, the applicant shall move in the appropriate court of appeals for an order authorizing the district court to consider the application."],[0,"(B) A motion in the court of appeals for an order authorizing the district court to consider a second or successive application shall be determined by a three-judge panel of the court of appeals."],[0,"(C) The court of appeals may authorize the filing of a second or successive application only if it determines that the application makes a prima facie showing that the application satisfies the requirements of this subsection."],[0,"(D) The court of appeals shall grant or deny the authorization to file a second or successive application not later than 30 days after the filing of the motion."],[0,"(E) The grant or denial of an authorization by a court of appeals to file a second or successive application shall not be appealable and shall not be the subject of a petition for rehearing or for a writ of certiorari."],[0,"(4) A district court shall dismiss any claim presented in a second or successive application that the court of appeals has authorized to be filed unless the applicant shows that the claim satisfies the requirements of this section."],[0,"(c) In a habeas corpus proceeding brought in behalf of a person in custody pursuant to the judgment of a State court, a prior judgment of the Supreme Court of the United States on an appeal or review by a writ of certiorari at the instance of the prisoner of the decision of such State court, shall be conclusive as to all issues of fact or law with respect to an asserted denial of a Federal right which constitutes ground for discharge in a habeas corpus proceeding, actually adjudicated by the Supreme Court therein, unless the applicant for the writ of habeas corpus shall plead and the court shall find the existence of a material and controlling fact which did not appear in the record of the proceeding in the Supreme Court and the court shall further find that the applicant for the writ of habeas corpus could not have caused such fact to appear in such record by the exercise of reasonable diligence."],[0,"(d)(1) A 1-year period of limitation shall apply to an application for a writ of habeas corpus by a person in custody pursuant to the judgment of a State court. The limitation period shall run from the latest of—"],[1,"(A) the date on which the judgment became final by the conclusion of direct review or the expiration of the time for seeking such review;"],[1,"(B) the date on which the impediment to filing an application created by State action in violation of the Constitution or laws of the United States is removed, if the applicant was prevented from filing by such State action;"],[1,"(C) the date on which the constitutional right asserted was initially recognized by the Supreme Court, if the right has been newly recognized by the Supreme Court and made retroactively applicable to cases on collateral review; or"],[1,"(D) the date on which the factual predicate of the claim or claims presented could have been discovered through the exercise of due diligence."],[0,"(2) The time during which a properly filed application for State post-conviction or other collateral review with respect to the pertinent judgment or claim is pending shall not be counted toward any period of limitation under this subsection."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2244?type=usc&year=mostrecent&link-type=html"},"by":{"1":"16, 16, 16, 16"},"q":[{"src":"brief","b":1,"text":"that was not presented in a prior ap- plication * * * unless","cite":"28 U.S.C. 2244(b)(2)"},{"src":"brief","b":1,"text":"the applicant shows that the claim relies on a new rule of constitutional law, made retroactive to cases on collateral review by the Supreme Court, that was previously unavailable.","cite":"28 U.S.C. 2244(b)(2)(A)"}]},{"t":"case","label":"Adam v. Hagan","cite":"325 F.2d 719","y":1963,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/325/719/","by":{"2":"3"}},{"t":"case","label":"Bailey v. United States","cite":"516 U.S. 137","y":1995,"id":"1995/94-7448","sc":1,"by":{"2":"21-22"}},{"t":"case","label":"Black v. United States","cite":"301 F.2d 418","y":1962,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/301/418/","by":{"2":"3"}},{"t":"case","label":"Cohen v. United States","cite":"593 F.2d 766","y":1979,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/593/766/","by":{"2":"5"}},{"t":"case","label":"Crismond v. Blackwell","cite":"333 F.2d 374","y":1964,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/333/374/","by":{"2":"3"}},{"t":"case","label":"Cutter v. Wilkinson","cite":"544 U.S. 709","y":2005,"id":"2004/03-9877","sc":1,"by":{"2":"20"},"q":[{"src":"brief","b":2,"text":"a court of review, not of first view.","cite":"544 U.S. 709, 718 n.7"}]},{"t":"case","label":"Edwards v. Walker","cite":"349 F. Supp. 1295","y":1972,"court":"C.D. Cal.","url":"https://www.courtlistener.com/c/F.%20Supp./349/1295/","by":{"2":"3"}},{"t":"case","label":"Mead v. Parker","cite":"464 F.2d 1108","y":1972,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/464/1108/","by":{"2":"5"}},{"t":"case","label":"Ortiz v. United States","cite":"138 S. Ct. 2165","y":2018,"id":"2017/16-1423","sc":1,"by":{"2":"8"},"q":[{"src":"argument","who":"Chief Justice Roberts","text":"We'll hear argument first this morning in Case 21-857, Jones versus Hendrix. Mr. Ortiz. ORAL ARGUMENT OF DANIEL R. ORTIZ ON BEHALF OF THE PETITIONER"},{"src":"argument","who":"Mr. Ortiz","text":"Well, Your Honor, this Court itself in the Ortiz case very recently declared that court martials preexisted the Constitution let alone an act of Congress."},{"src":"argument","who":"Chief Justice Roberts","text":"Thank you, counsel. Mr. Ortiz, rebuttal. REBUTTAL ARGUMENT OF DANIEL R. ORTIZ ON BEHALF OF THE PETITIONER"}]},{"t":"case","label":"Reed v. Farley","cite":"512 U.S. 339","y":1994,"id":"1993/93-5418","sc":1,"by":{"2":"22"},"q":[{"src":"brief","b":2,"text":"[C]laims will ordinarily not be entertained under § 2255 that have already been rejected on direct review.","cite":"512 U.S. 339, 358"}]},{"t":"case","label":"Reed v. Ross","cite":"468 U.S. 1","y":1984,"id":"1983/83-218","sc":1,"by":{"2":"21, 22"},"q":[{"src":"brief","b":2,"text":"nearunanimous body of lower court authority,","cite":"468 U.S. at 17"}]},{"t":"case","label":"Shaffer v. Heitner","cite":"433 U.S. 186","y":1977,"id":"1976/75-1812","sc":1,"by":{"2":"13"},"q":[{"src":"brief","b":2,"text":"a diverse legal system such as our own.","cite":"433 U.S. 186, 225"}]},{"t":"case","label":"Smith v. Settle","cite":"302 F.2d 142","y":1962,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/302/142/","by":{"2":"3"}},{"t":"case","label":"Solorio v. United States","cite":"483 U.S. 435","y":1987,"id":"1986/85-1581","sc":1,"by":{"2":"8"},"q":[{"src":"brief","b":2,"text":"explain[s] that Congress ‘empowered courts-martial to try servicemen for the crimes proscribed by the [Uniform Code of Military Justice.]’","cite":"483 U.S. at 438"}]},{"t":"case","label":"Stidham v. Swope","cite":"82 F. Supp. 931","y":1949,"court":"N.D. Cal","url":"https://www.courtlistener.com/c/F.%20Supp./82/931/","by":{"2":"3, 4"}},{"t":"case","label":"Strickler v. Greene","cite":"527 U.S. 263","y":1999,"id":"1998/98-5864","sc":1,"by":{"2":"22"},"q":[{"src":"brief","b":2,"text":"there is a reasonable probability that the jury would have returned a different verdict","cite":"527 U.S. 263, 296"}]},{"t":"case","label":"Trevino v. Thaler","cite":"569 U.S. 413","y":2013,"id":"2012/11-10189","sc":1,"by":{"2":"18"}},{"t":"case","label":"United States v. Fox","cite":"454 F.2d 593","y":1971,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/454/593/","by":{"2":"19"},"q":[{"src":"brief","b":2,"text":"that Gutknecht * * * did not affect his conviction.","cite":"454 F.2d 593"}]},{"t":"case","label":"United States v. Frady","cite":"456 U.S. 152","y":1982,"id":"1981/80-1595","sc":1,"by":{"2":"22"}},{"t":"case","label":"Williams v. United States","cite":"323 F.2d 672","y":1963,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/323/672/","by":{"2":"3"}},{"t":"usc","label":"10 U.S.C. § 941","url":"https://www.law.cornell.edu/uscode/text/10/941","subs":["(2016)"],"by":{"2":"9, 9"}}]};